import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.yse_Y9k2.js";const h=JSON.parse('{"title":"Commandes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/commands.md","filePath":"fr/commands.md"}'),o={name:"fr/commands.md"};function i(r,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="commandes" tabindex="-1">Commandes <a class="header-anchor" href="#commandes" aria-label="Permalink to &quot;Commandes&quot;">​</a></h1><p>La plupart des commandes lisent le dossier de configuration (<code>--dir</code>, <code>.</code> par défaut) et parlent à Notion via <code>ntn</code>. <code>init</code> ne prend pas de <code>--dir</code> — elle ne fait que vérifier <code>ntn</code> — et <code>version</code> ne fait ni l&#39;un ni l&#39;autre : elle affiche seulement son numéro. Seules <code>import</code> et <code>apply</code> écrivent — dans Notion et dans le state.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Écrit dans Notion</th><th>Écrit le state</th></tr></thead><tbody><tr><td><code>init</code></td><td>non</td><td>non</td></tr><tr><td><code>plan</code></td><td>non</td><td>non</td></tr><tr><td><code>diff</code></td><td>non</td><td>non</td></tr><tr><td><code>apply</code></td><td>oui</td><td>oui</td></tr><tr><td><code>import</code></td><td>non</td><td>oui</td></tr><tr><td><code>version</code></td><td>non</td><td>non</td></tr></tbody></table><h2 id="init" tabindex="-1">init <a class="header-anchor" href="#init" aria-label="Permalink to &quot;init&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notion-seed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # vérifie que ntn est présent, assez récent et authentifié</span></span></code></pre></div><p>Elle n&#39;écrit rien : elle vérifie seulement que <code>ntn</code> est présent, assez récent et authentifié, avant que toute autre commande ne tente de joindre Notion.</p><h2 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;plan&quot;">​</a></h2><p><code>plan</code> calcule et affiche les changements, sans rien appliquer.</p><h3 id="sortie" tabindex="-1">Sortie <a class="header-anchor" href="#sortie" aria-label="Permalink to &quot;Sortie&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ntn 0.22.11 — workspace Example Space (33333333-3333-4333-8333-333333333333)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Plan: 2 to add, 0 to change, 0 to destroy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  + database.projects (new)</span></span>
<span class="line"><span>      + name &quot;Projects&quot;</span></span>
<span class="line"><span>      + property &quot;Name&quot; (title)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  + database.tasks (new)</span></span>
<span class="line"><span>      + name &quot;Tasks&quot;</span></span>
<span class="line"><span>      + property &quot;Estimate&quot; (number)</span></span>
<span class="line"><span>      + property &quot;Name&quot; (title)</span></span></code></pre></div><p>Texte brut, sans couleur : la sortie doit rester lisible dans un pipe et en CI. Le plan part sur stdout, les attentes de retry sur stderr — stdout ne porte que le plan, pour qu&#39;il reste identique entre deux runs.</p><p>Un plan bloqué sort en code non nul — une ressource gérée que Notion ne connaît plus, par exemple. Le coût mesuré, lui, ne fait sortir en erreur que si vous l&#39;avez demandé avec <a href="#en-ci"><code>--fail-on</code></a>.</p><h3 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Défaut</th><th>Rôle</th></tr></thead><tbody><tr><td><code>--dir</code></td><td><code>.</code></td><td>dossier de configuration</td></tr><tr><td><code>--skip-preflight</code></td><td><code>false</code></td><td>mode entièrement hors ligne : ni vérification de <code>ntn</code>, ni vérification de la page parente. Valide la configuration et rend le plan sans aucun appel réseau — les ressources déjà importées ne sont pas comparées au réel dans ce mode, et ressortent sous <code>Not compared</code> plutôt que sous <code>No changes</code></td></tr><tr><td><code>--rate</code></td><td><code>5</code></td><td>plafond d&#39;appels API par seconde</td></tr><tr><td><code>--burst</code></td><td><code>10</code></td><td>appels tolérés en rafale</td></tr><tr><td><code>--fail-on</code></td><td>vide</td><td>classes de changement qui font sortir en code non nul — voir <a href="#en-ci">En CI</a>. Vide : rien ne fait échouer</td></tr></tbody></table><p><code>import</code> prend <code>--dir</code>, <code>--rate</code> et <code>--burst</code>, mais refuse <code>--skip-preflight</code> — la commande lit l&#39;état réel, elle n&#39;a aucun sens hors ligne — et <code>--fail-on</code>, puisqu&#39;elle ne calcule aucun plan.</p><h3 id="ce-qui-peut-etre-compte-et-ce-qui-ne-peut-pas" tabindex="-1">Ce qui peut être compté, et ce qui ne peut pas <a class="header-anchor" href="#ce-qui-peut-etre-compte-et-ce-qui-ne-peut-pas" aria-label="Permalink to &quot;Ce qui peut être compté, et ce qui ne peut pas&quot;">​</a></h3><p>Compter demande un filtre, et <code>notion-seed</code> n&#39;en sait construire un que pour <code>select</code>, <code>status</code> et <code>multi_select</code>.</p><p>Un <strong>retrait d&#39;option</strong> est donc toujours chiffré : les options n&#39;existent que sur ces trois types.</p><p>Une <strong>destruction</strong> l&#39;est aussi, sans filtre : le compte porte sur toutes les lignes du data source de la database — celui que le plan vient de relire —, celles qui partent à la corbeille avec elle. Une database qui porte plusieurs data sources les emporte tous, mais un seul est compté : la ligne et l&#39;agrégat disent alors « at least N row(s) », et combien de data sources n&#39;ont pas été comptés. Elle reste <code>destructive</code> quel que soit ce compte, 0 compris.</p><p>Un <strong>changement de type</strong> n&#39;est chiffré que si la colonne de départ est de l&#39;un d&#39;eux. Des trois couples dangereux ci-dessous, un seul l&#39;est — et seul <code>multi_select</code> → <code>select</code> fait partie des comportements mesurés sur la présentation (<a href="/notion-seed/fr/#pourquoi">Pourquoi</a>) :</p><table tabindex="0"><thead><tr><th>Couple</th><th>Chiffré ?</th></tr></thead><tbody><tr><td><code>multi_select</code> → <code>select</code></td><td>oui — la colonne de départ est filtrable</td></tr><tr><td><code>rich_text</code> → <code>number</code></td><td>non</td></tr><tr><td><code>checkbox</code> → <code>number</code></td><td>non</td></tr></tbody></table><p>Dans les deux derniers cas, la ligne ne porte pas de chiffre mais le dit :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      ~ property &quot;Notes&quot; — rich_text → number  [silent rewrite]</span></span>
<span class="line"><span>          → actual impact unknown: notion-seed cannot count the rows of a rich_text property.</span></span></code></pre></div><p>La classe reste celle de la mesure — vous savez que le changement est dangereux, vous ne savez pas sur combien de lignes. Et <code>--fail-on=unknown</code> les attrape.</p><p>Vous êtes garant de votre base. notion-seed est garant de ce que vous savez en appuyant sur entrée. En CI, <a href="#en-ci"><code>--fail-on</code></a> rend la décision au workflow.</p><h2 id="diff" tabindex="-1">diff <a class="header-anchor" href="#diff" aria-label="Permalink to &quot;diff&quot;">​</a></h2><p><code>diff</code> est l&#39;équivalent en lecture seule de <code>plan</code>, sans toucher au state.</p><p><code>diff</code> est aujourd&#39;hui identique à <code>plan</code>, puisque <code>plan</code> n&#39;écrit pas encore de state. Les deux restent distinctes pour que l&#39;usage en CI soit stable le jour où <code>plan</code> y touchera.</p><h2 id="apply" tabindex="-1">apply <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;apply&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notion-seed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span></code></pre></div><p><code>apply</code> recalcule le plan, l&#39;affiche, demande confirmation, puis écrit. Il ne prend aucun argument : il n&#39;y a pas de fichier de plan à rejouer, donc pas de plan périmé à appliquer par mégarde.</p><h3 id="ce-qu-il-ecrit" tabindex="-1">Ce qu&#39;il écrit <a class="header-anchor" href="#ce-qu-il-ecrit" aria-label="Permalink to &quot;Ce qu&#39;il écrit&quot;">​</a></h3><p>Les <strong>créations</strong>. Une database déclarée dans le YAML et absente du state est créée dans la page parente, relue, puis inscrite dans le state. Le state est sauvegardé après <em>chaque</em> création : une interruption laisse un fichier exactement vrai, jamais une database créée sans ancre — donc jamais un doublon au run suivant.</p><p>La relecture n&#39;est pas du zèle. Elle rapporte les ids d&#39;options, sans lesquels le state est aveugle à la dérive, et elle confronte le réel à ce qui avait été annoncé. Si l&#39;API n&#39;a pas écrit ce que le plan promettait, <code>apply</code> le dit — sur sa propre écriture.</p><p>Les <strong>modifications</strong>. Une database déjà ancrée par le state est écrite en deux appels, toujours dans cet ordre :</p><ol><li><code>PATCH /v1/databases/{id}</code> — le nom, la description et l&#39;icône, s&#39;ils changent ;</li><li><code>PATCH /v1/data_sources/{id}</code> — les propriétés qui portent une ligne dans le plan, et elles seules.</li></ol><p>Ce qui part est exactement ce que le plan a affiché : une propriété déclarée mais identique au réel ne part pas, une propriété non déclarée non plus. Les options existantes sont transmises avec leur id, les neuves sans : l&#39;API leur en crée un, que la relecture rapporte au state. Sous un changement de type, les options sont recréées : seules celles du YAML partent, sans id, et chaque option actuelle que le YAML ne redéclare pas sous le même nom ressort en <code>-</code>, avec le nombre de lignes qu&#39;elle vide. Seul <code>select</code> → <code>multi_select</code> a été mesuré ; les autres couples entre <code>select</code>, <code>multi_select</code> et <code>status</code> suivent la même règle, sans l&#39;avoir été.</p><p>L&#39;ordre est choisi pour l&#39;échec. Si le second appel échoue, le nom et l&#39;icône sont à jour et <strong>aucune donnée de ligne n&#39;a été touchée</strong> — l&#39;échec le moins coûteux. <code>apply</code> le dit, et inscrit dans le state ce qui est passé.</p><p>Les <strong>destructions</strong>. Une database que le state ancre, que le YAML ne déclare plus et que Notion porte encore est mise à la corbeille par un seul appel, <code>PATCH /v1/databases/{id}</code> avec <code>{&quot;in_trash&quot;:true}</code>, puis son entrée est retirée du state. L&#39;entrée n&#39;est retirée que si la réponse de l&#39;API confirme la corbeille : sinon elle est gardée, et <code>apply</code> le signale comme un écart. <code>plan</code> et <code>apply</code> disent avant combien de lignes partent avec elle ; si le comptage échoue, la ligne dit que ce nombre n&#39;est pas mesuré, jamais 0. <code>lifecycle.prevent_destroy</code> n&#39;y change rien — voir <a href="/notion-seed/fr/yaml#lifecycle-des-accuses-de-lecture">lifecycle</a>. Une database mise à la corbeille se restaure depuis la corbeille de Notion ; pour que notion-seed la gère de nouveau, redéclarez-la puis lancez <code>notion-seed import</code>.</p><p>Renommer la <code>key</code> d&#39;une database dans le YAML n&#39;est pas un renommage pour notion-seed, qui n&#39;a que la key pour ancrer l&#39;identité : l&#39;ancienne key en ressort orpheline et part à la corbeille, la nouvelle est créée vide, et <code>plan</code> montre les deux séparément. Pour garder la database, gardez sa <code>key</code> — avec une <code>key</code> explicite, <code>name</code> peut changer librement ; sans elle, la key est dérivée de <code>name</code> et un renommage la déplace (voir <a href="/notion-seed/fr/yaml#databases-yaml">databases/*.yaml</a>) — ou, si la key a déjà changé, ré-attachez la database existante à la nouvelle key avec <code>notion-seed import</code> avant de lancer <code>apply</code>.</p><p>Il retire aussi les <strong>entrées de state obsolètes</strong> : une ressource que le YAML ne déclare plus et qui a déjà été supprimée dans Notion. C&#39;est un nettoyage local, rien n&#39;est écrit dans Notion — à ne pas confondre avec une destruction, qui écrit, et que la confirmation annonce sur sa propre ligne.</p><h3 id="ce-qu-il-retient" tabindex="-1">Ce qu&#39;il retient <a class="header-anchor" href="#ce-qu-il-retient" aria-label="Permalink to &quot;Ce qu&#39;il retient&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Une limite de l&#39;API, pas un jugement</p><p>Renommer une option ou changer sa couleur est le seul changement déclaré que notion-seed refuse d&#39;écrire : l&#39;API ne sait pas l&#39;exprimer.</p></div><p>Ce que l&#39;API ne sait pas exprimer ressort sous <code>Withheld — migration required</code> : ce n&#39;est pas une limite de cette version, et attendre n&#39;y changera rien — voir <a href="/notion-seed/fr/#ce-que-l-api-ne-sait-pas-faire">Ce que l&#39;API ne sait pas faire</a>. <code>apply</code> sort en code non nul tant qu&#39;il reste une ressource retenue — un apply qui ne converge pas doit être bruyant en CI.</p><p>Une ressource retenue n&#39;est pas touchée du tout : aucun appel ne part pour elle. Une ressource écrite l&#39;est en entier, à une exception près, qui n&#39;est jamais silencieuse : une modification peut s&#39;arrêter entre ses deux appels — voir <a href="#en-cas-d-echec">En cas d&#39;échec</a>.</p><p>La migration se fait à la main, avec le nombre de lignes que <code>plan</code> a compté :</p><ol><li>créer la nouvelle option dans Notion ;</li><li>y déplacer les lignes que le plan a comptées ;</li><li>retirer l&#39;ancienne option, puis relancer.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ~ database.tasks  [migration required]</span></span>
<span class="line"><span>      ~ option &quot;Fait&quot; → &quot;Terminé&quot; (property &quot;Statut&quot;) — the API returns 200 without changing anything: create, migrate the rows, then remove  [migration required]</span></span>
<span class="line"><span>          → 2 rows hold &quot;Fait&quot;: migrate them by hand before applying.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Withheld — migration required</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ~ database.tasks</span></span>
<span class="line"><span>      an option must be migrated by hand: the API can neither rename an option nor change its color</span></span>
<span class="line"><span>      → create the new option in Notion, move the rows counted above to it, remove the old one, then rerun</span></span></code></pre></div><p>C&#39;est le seul changement déclaré que notion-seed refuse d&#39;écrire — et ce n&#39;est pas un jugement sur le coût, c&#39;est une limite de l&#39;API. Écrire quand même inscrirait dans le state un état que Notion ne porte pas, et chaque run suivant afficherait une dérive fantôme.</p><h3 id="la-confirmation" tabindex="-1">La confirmation <a class="header-anchor" href="#la-confirmation" aria-label="Permalink to &quot;La confirmation&quot;">​</a></h3><p>Le mot <code>apply</code>, tapé en entier, après le plan et ce qui va se passer, par nature : créations, modifications, mises à la corbeille, et entrées de state obsolètes à retirer — chacune sur sa ligne, puisque la dernière n&#39;écrit rien dans Notion. La ligne <code>Impact</code> qu&#39;affiche <code>apply</code> ne compte que les ressources qu&#39;il va écrire : une ressource retenue en est exclue, puisqu&#39;<code>apply</code> ne causera pas ce qu&#39;elle coûterait. Sans ressource retenue, elle est identique à celle de <code>plan</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Impact: 1 database(s) in the trash with 3 row(s).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 database(s) will be moved to the trash in Notion.</span></span>
<span class="line"><span>Type &quot;apply&quot; to confirm:</span></span></code></pre></div><p>Elle ne lève rien de ce qui arrête la commande : un plan bloqué — une ressource gérée que Notion ne connaît plus — ou une classe refusée par <code>--fail-on</code> n&#39;atteint jamais le prompt.</p><p>Hors terminal, <code>apply</code> exige <code>--auto-approve</code> plutôt que de s&#39;exécuter parce que personne ne répondait.</p><p>Dans un terminal, une fin d&#39;entrée au prompt — <code>Ctrl-D</code> — refuse elle aussi, avec son propre message : <code>confirmation interrupted (end of input): nothing was applied</code>. Une entrée branchée sur <code>/dev/null</code> n&#39;est pas un terminal, et réclame <code>--auto-approve</code>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Défaut</th><th>Rôle</th></tr></thead><tbody><tr><td><code>--auto-approve</code></td><td><code>false</code></td><td>applique sans demander confirmation (mode CI)</td></tr></tbody></table><p><code>apply</code> partage <code>--dir</code>, <code>--rate</code>, <code>--burst</code> et <code>--fail-on</code> avec <code>plan</code>, et refuse <code>--skip-preflight</code> : écrire hors ligne n&#39;a pas de sens. <code>--fail-on</code> y est vérifié <strong>avant</strong> la confirmation et avant la moindre écriture.</p><h3 id="en-cas-d-echec" tabindex="-1">En cas d&#39;échec <a class="header-anchor" href="#en-cas-d-echec" aria-label="Permalink to &quot;En cas d&#39;échec&quot;">​</a></h3><p>Aucun rollback : archiver ce qu&#39;on vient de créer serait une destruction que personne n&#39;a demandée. Ce qui a été créé, modifié ou mis à la corbeille reste écrit, et le state le reflète.</p><p>Une modification peut s&#39;arrêter <strong>entre ses deux appels</strong> : le nom, la description ou l&#39;icône sont passés, les propriétés non, et aucune donnée de ligne n&#39;a été touchée. <code>apply</code> nomme ce qui est passé, l&#39;inscrit dans le state, et relancer <code>notion-seed plan</code> montre ce qui reste.</p><p>Une database dont une page ancêtre est à la corbeille se lit comme vivante, mais refuse toute écriture. <code>apply</code> le diagnostique et demande de restaurer la page parente, plutôt que de relayer le <code>404</code> de l&#39;API, qui accuse à tort le partage avec l&#39;intégration.</p><p>Quand c&#39;est la page de <code>workspace.parent_page_id</code> elle-même qui est à la corbeille, <code>plan</code> et <code>apply</code> s&#39;arrêtent dès la vérification de départ, avant tout plan et donc avant toute écriture : restaurez-la, ou faites pointer <code>parent_page_id</code> vers une page vivante. C&#39;est vrai aussi quand c&#39;est une page au-dessus d&#39;elle qui est à la corbeille : Notion le signale sur la page parente. <code>--skip-preflight</code> saute cette vérification comme les autres.</p><p>Une mise à la corbeille qui échoue — refus de l&#39;API, <code>404</code>, issue inconnue — laisse l&#39;entrée de state <strong>en place</strong> : <code>apply</code> s&#39;arrête et renvoie à <code>notion-seed plan</code>, qui relit le réel. Une database déjà partie y ressort en entrée de state obsolète, qu&#39;un <code>apply</code> suivant retire sans rien écrire ; une database encore là y ressort en destruction. Abandonner l&#39;identité sur la foi d&#39;un échec rendrait invisible une database peut-être encore vivante.</p><p>Sous une page ancêtre déjà à la corbeille, Notion refuse aussi la mise à la corbeille, et la database y part de toute façon avec sa page. <code>apply</code> propose les deux issues : restaurer la page parente puis relancer <code>apply</code>, ou supprimer définitivement la page parente depuis la corbeille de Notion, puis relancer <code>notion-seed plan</code> : si Notion ne connaît plus la database, son entrée y ressort en entrée de state obsolète, qu&#39;un <code>apply</code> suivant retire sans rien écrire.</p><p>Si l&#39;issue d&#39;une création est <strong>inconnue</strong> — un timeout ne dit pas si le serveur a appliqué la mutation — <code>apply</code> s&#39;arrête net sans enchaîner, et nomme la database, la page parente et la marche à suivre : vérifier dans Notion, puis <code>notion-seed import</code> si elle existe. Pour une modification, l&#39;identité est déjà dans le state : <code>notion-seed plan</code> suffit à voir ce que Notion porte.</p><h2 id="import" tabindex="-1">import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;import&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notion-seed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> database.tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.notion.so/space/Tasks-1b2c3d4e5f60...</span></span></code></pre></div><p>La key doit être déclarée dans <code>databases/</code>. <code>import</code> adopte la database telle qu&#39;elle est, sans exiger qu&#39;elle corresponde déjà au YAML — c&#39;est le <code>plan</code> suivant qui affiche l&#39;écart.</p><p>Les <code>key</code> d&#39;options sont accrochées à cet instant, en joignant sur le nom. Une option présente dans Notion et absente du YAML est enregistrée sans key et comptée dans la sortie :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>database.tasks imported — id 1b2c3d4e-5f60-4a1b-8c2d-3e4f5a6b7c8d (8 properties, 2 options without a config key)</span></span></code></pre></div><p>Voir <a href="/notion-seed/fr/yaml#ce-qui-n-est-pas-declare">ce qui n&#39;est pas déclaré</a>.</p><h2 id="version" tabindex="-1">version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;version&quot;">​</a></h2><p>Affiche la version de notion-seed.</p><p>Le binaire installé par <code>go install</code> annonce <code>0.0.0-dev</code> : la version n&#39;est injectée qu&#39;au build de release.</p><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><p><code>notion-seed.state.json</code>, à côté de <code>workspace.yaml</code>, retient l&#39;identité Notion de chaque ressource gérée et son dernier état appliqué. <strong>Versionnez-le</strong> : il ne contient aucun secret, et c&#39;est lui qui rend le plan reproductible entre machines et en CI.</p><p>Sans lui, <code>notion-seed</code> n&#39;a aucune ancre d&#39;identité : toute database déclarée ressort en création, même si elle existe déjà dans Notion.</p><p>C&#39;est ce fichier qui permet de distinguer « le YAML a changé » de « quelqu&#39;un a changé Notion à la main ». Le second cas s&#39;affiche sous la section <code>Drift detected outside notion-seed</code>, avant le plan qui ramène le réel vers le YAML.</p><p>Seules les commandes <code>import</code> et <code>apply</code> l&#39;écrivent. <code>plan</code> et <code>diff</code> lisent le réel mais n&#39;y touchent jamais : un <code>plan</code> en CI ne peut donc pas produire un diff git surprise, et une dérive ne s&#39;efface pas d&#39;elle-même.</p><h2 id="en-ci" tabindex="-1">En CI <a class="header-anchor" href="#en-ci" aria-label="Permalink to &quot;En CI&quot;">​</a></h2><p>Par défaut, un plan qui coûte cher s&#39;affiche et sort en <code>0</code> : notion-seed mesure, il ne décide pas. <code>--fail-on</code> énumère les classes sur lesquelles <em>votre</em> workflow, lui, veut s&#39;arrêter.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notion-seed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail-on=silent-rewrite,destructive</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Valeur</th><th>Ce qu&#39;elle attrape</th></tr></thead><tbody><tr><td><code>destructive</code></td><td>une donnée est perdue, sans qu&#39;aucune fausse valeur soit écrite</td></tr><tr><td><code>silent-rewrite</code></td><td>une donnée est remplacée par une autre, sans trace</td></tr><tr><td><code>unknown</code></td><td>l&#39;impact n&#39;a pas pu être mesuré : type hors table, comptage en échec, ou hors ligne</td></tr><tr><td><code>migration</code></td><td>l&#39;API accepte la requête et ne change rien : il faut migrer les lignes à la main</td></tr></tbody></table><p>Cinq choses à savoir :</p><ul><li>La liste est <strong>énumérée, pas un seuil</strong>. <code>safe</code>, <code>destructive</code> et <code>silent rewrite</code> forment bien une échelle, mais <code>unknown impact</code> n&#39;y a pas de place : un changement non mesuré peut se révéler anodin comme catastrophique. Demander <code>destructive</code> ne demande donc pas « tout ce qui est au moins aussi grave » — nommez chaque classe que vous voulez attraper.</li><li>Une valeur inconnue — une faute de frappe dans un nom de classe — est refusée <strong>avant le moindre appel réseau</strong>, et le message liste les valeurs acceptées. Sinon une CI mal configurée passerait au vert en croyant se protéger, ce qui est le pire mode d&#39;échec possible pour ce flag.</li><li>Le plan est <strong>rendu quand même</strong> avant la sortie en erreur : le code de retour dit qu&#39;il faut regarder, la sortie dit quoi.</li><li>Le déclenchement se fait sur les lignes de détail, avec leur classe mesurée. Une option que personne n&#39;utilise est classée <code>safe</code> et n&#39;attrape rien, même sur une propriété <code>status</code> — c&#39;est tout l&#39;intérêt d&#39;avoir compté.</li><li>Un comptage <strong>en échec</strong> bascule sa ligne en <code>unknown impact</code>. Un <code>403</code>, un <code>429</code> qui n&#39;a plus de patience, une réponse que notion-seed ne reconnaît pas : la ligne n&#39;est alors plus classée <code>destructive</code> ni <code>silent rewrite</code>, donc un <code>--fail-on=destructive,silent-rewrite</code> ne l&#39;attrape plus et sort en <code>0</code>. Ajoutez <code>unknown</code> à votre liste si vous voulez que le garde-fou tienne même quand l&#39;API refuse de compter — sans quoi une CI se croit protégée précisément le jour où elle ne l&#39;est pas. Seule exception : une destruction dont le comptage de lignes échoue reste <code>destructive</code>, puisque la database part à la corbeille quel qu&#39;en soit le compte.</li></ul><p><code>--fail-on</code> vaut aussi pour <code>apply</code>, où il est vérifié avant toute écriture. Attention à <code>--skip-preflight</code> : hors ligne, rien n&#39;est compté, et chaque ligne qui aurait pu coûter ressort en <code>unknown impact</code> — un <code>--fail-on=destructive</code> n&#39;y attrape donc plus rien, alors que <code>--fail-on=unknown</code> les attrape toutes.</p>`,86)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
